// C++ — Segment Tree (sum), node array skeleton and build

class SegmentTree {
    vector<long long> tree;
    int n;

public:
    SegmentTree(vector<long long>& arr) {
        n = arr.size();
        tree.assign(4 * n, 0);
        if (n > 0) build(arr, 1, 0, n - 1);
    }

    void build(vector<long long>& arr, int node, int lo, int hi) {
        if (lo == hi) {
            tree[node] = arr[lo];      // leaf: copy the raw element
            return;
        }
        int mid = lo + (hi - lo) / 2;
        build(arr, 2 * node, lo, mid);
        build(arr, 2 * node + 1, mid + 1, hi);
        tree[node] = tree[2 * node] + tree[2 * node + 1];   // combine on the way up
    }
};

// Add to the SegmentTree class above

void update(int node, int lo, int hi, int idx, long long val) {
    if (lo == hi) {
        tree[node] = val;      // reached the target leaf
        return;
    }
    int mid = lo + (hi - lo) / 2;
    if (idx <= mid) update(2 * node, lo, mid, idx, val);
    else            update(2 * node + 1, mid + 1, hi, idx, val);
    tree[node] = tree[2 * node] + tree[2 * node + 1];   // recombine on the way back up
}

// call as: update(1, 0, n - 1, idx, val);

// Add to the SegmentTree class above

long long query(int node, int lo, int hi, int l, int r) {
    if (r < lo || hi < l) return 0;                    // no overlap: identity for sum

    if (l <= lo && hi <= r) return tree[node];          // full overlap: use directly

    int mid = lo + (hi - lo) / 2;                       // partial overlap: recurse both
    long long leftSum  = query(2 * node,     lo,     mid, l, r);
    long long rightSum = query(2 * node + 1, mid + 1, hi,  l, r);
    return leftSum + rightSum;
}

// call as: query(1, 0, n - 1, l, r);

// C++ — Segment Tree with Lazy Propagation (range add, range sum)

class LazySegmentTree {
    vector<long long> tree, lazy;
    int n;

public:
    LazySegmentTree(int size) {
        n = size;
        tree.assign(4 * n, 0);
        lazy.assign(4 * n, 0);
    }

    void build(vector<long long>& arr, int node, int lo, int hi) {
        if (lo == hi) {
            tree[node] = arr[lo];
            return;
        }
        int mid = lo + (hi - lo) / 2;
        build(arr, 2 * node, lo, mid);
        build(arr, 2 * node + 1, mid + 1, hi);
        tree[node] = tree[2 * node] + tree[2 * node + 1];
    }

    void pushDown(int node, int lo, int hi) {
        if (lazy[node] == 0) return;
        int mid = lo + (hi - lo) / 2;
        int left = 2 * node, right = 2 * node + 1;

        tree[left] += lazy[node] * (mid - lo + 1);
        lazy[left] += lazy[node];

        tree[right] += lazy[node] * (hi - mid);
        lazy[right] += lazy[node];

        lazy[node] = 0;   // fully resolved, nothing pending here anymore
    }

    void updateRange(int node, int lo, int hi, int l, int r, long long val) {
        if (r < lo || hi < l) return;                    // no overlap

        if (l <= lo && hi <= r) {                         // full overlap
            tree[node] += val * (hi - lo + 1);
            lazy[node] += val;
            return;
        }

        pushDown(node, lo, hi);                           // partial overlap: about
                                                            // to touch children
        int mid = lo + (hi - lo) / 2;
        updateRange(2 * node, lo, mid, l, r, val);
        updateRange(2 * node + 1, mid + 1, hi, l, r, val);
        tree[node] = tree[2 * node] + tree[2 * node + 1];
    }

    long long query(int node, int lo, int hi, int l, int r) {
        if (r < lo || hi < l) return 0;                   // no overlap
        if (l <= lo && hi <= r) return tree[node];         // full overlap

        pushDown(node, lo, hi);                           // partial overlap: about
                                                            // to touch children
        int mid = lo + (hi - lo) / 2;
        long long leftSum  = query(2 * node,     lo,     mid, l, r);
        long long rightSum = query(2 * node + 1, mid + 1, hi,  l, r);
        return leftSum + rightSum;
    }
};

// call as: updateRange(1, 0, n - 1, l, r, val);
//          query(1, 0, n - 1, l, r);

// Only the combine step and identity change for a min segment tree

void build(vector<long long>& arr, int node, int lo, int hi) {
    if (lo == hi) { tree[node] = arr[lo]; return; }
    int mid = lo + (hi - lo) / 2;
    build(arr, 2 * node, lo, mid);
    build(arr, 2 * node + 1, mid + 1, hi);
    tree[node] = min(tree[2 * node], tree[2 * node + 1]);   // was +
}

long long query(int node, int lo, int hi, int l, int r) {
    if (r < lo || hi < l) return LLONG_MAX;                  // identity for min
    if (l <= lo && hi <= r) return tree[node];
    int mid = lo + (hi - lo) / 2;
    return min(query(2 * node, lo, mid, l, r),
               query(2 * node + 1, mid + 1, hi, l, r));
}
